u as (select c.*, 'https://sansad.in/getFile/loksabhaquestions/annex/' || session || '/' || stem || '.pdf?source=pqals' url,
             'pq:ls:' || session || ':' || stem k, case when stem like 'AS%' then 'STARRED' else 'UNSTARRED' end qtype from c),
held as (select u.stem,
   exists(select 1 from public.documents x where x.desk_tier = 'national'
            and (x.file_url = u.url or x.file_url like 'https://sansad.in/getFile/loksabhaquestions/annex/' || u.session || '/' || u.stem || '.pdf%')) by_url,
   exists(select 1 from public.documents x where x.desk_tier = 'national' and x.metadata->>'document_key_suggested' = u.k) by_key,
   exists(select 1 from public.documents x where x.desk_tier = 'national' and x.desk_feature = 'Parliamentary Question Database'
            and lower(regexp_replace(coalesce(x.metadata->>'source_path', ''), '^.*/', '')) = lower(u.session || '_' || u.stem || '.pdf')) by_path
 from u),
r as (select u.stem, u.sig, q.row_key::text row_key,
        md5(concat_ws('|', public.pq_norm(q.row->>'house'), public.pq_norm(q.row->>'subject'), public.pq_norm(q.row->>'ministry'), public.pq_date(q.row->>'date'))) rsig,
        public.pq_answer_key(q.row->>'source_url') = u.k key_ok,
        upper(coalesce(q.row->>'question_type', '')) = u.qtype type_ok,
        left(md5(coalesce(public.pq_norm(q.row->>'mp_name'), '')), 8) = any(u.asked) member_ok,
        q.row->>'house' = 'Lok Sabha' house_ok
      from u join public.desk_rows q on q.tier = 'national' and q.feature = 'Parliamentary Question Database' and q.row->>'source_url' = u.url),
s as (select u.stem, (select array_agg(row_key order by row_key) from r where r.stem = u.stem) live,
             (select array_agg(p order by p) from unnest(u.prow) p) pack from u)
select (select count(*) from u) cands,
       (select count(*) filter (where by_url) from held) held_by_url,
       (select count(*) filter (where by_key) from held) held_by_key,
       (select count(*) filter (where by_path) from held) held_by_path,
       (select count(distinct stem) from r) stems_with_rows,
       (select count(*) from s where live = pack) rowsets_equal,
       (select count(*) from r) rows_,
       (select sum(cardinality(prow)) from u) pack_rows,
       (select count(*) filter (where key_ok) from r) key_ok,
       (select count(*) filter (where rsig = sig) from r) rows_corroborated,
       (select count(*) filter (where type_ok) from r) type_ok,
       (select count(*) filter (where member_ok) from r) member_ok,
       (select count(*) filter (where house_ok) from r) house_ok,
       (select count(distinct stem) filter (where rsig <> sig or not key_ok or not type_ok or not member_ok or not house_ok) from r) stems_mismatch,
       (select string_agg(distinct stem, ',') filter (where rsig <> sig or not key_ok or not type_ok or not member_ok or not house_ok) from r) mismatched,
       (select string_agg(stem, ',') from s where live is distinct from pack) rowset_differs;
rollback;
